(function(){"use strict";var ZAD_LS_KEY="zad_v2";var ZAD_VERSION="Z10";function readLocalState(){try{var raw=localStorage.getItem(ZAD_LS_KEY);if(!raw)return null;return JSON.parse(raw)}catch(e){return null}}function writeSyncMeta(fields){try{var raw=localStorage.getItem(ZAD_LS_KEY);if(!raw)return false;var state=JSON.parse(raw);if(!state.sync)state.sync={};Object.keys(fields).forEach(function(k){state.sync[k]=fields[k]});localStorage.setItem(ZAD_LS_KEY,JSON.stringify(state));return true}catch(e){return false}}function makeIdempotencyKey(log_date){return"z10-"+log_date+"-"+Date.now()}function todayDate(){var d=new Date;var mm=String(d.getMonth()+1).padStart(2,"0");var dd=String(d.getDate()).padStart(2,"0");return d.getFullYear()+"-"+mm+"-"+dd}function buildWorshipPayload(state,log_date){var payload={};if(state.worship!==undefined){payload.worship=state.worship}if(state.streak!==undefined){payload.streak=state.streak}if(state.takbeer_total!==undefined){payload.takbeer_total=state.takbeer_total}if(state.history&&state.history[log_date]!==undefined){payload.history_today=state.history[log_date]}return payload}function hashObject(obj){try{var str=JSON.stringify(obj);return"len:"+str.length+":check:"+simpleChecksum(str)}catch(e){return"err"}}function simpleChecksum(str){var hash=0;for(var i=0;i<str.length;i++){var chr=str.charCodeAt(i);hash=(hash<<5)-hash+chr;hash|=0}return Math.abs(hash).toString(16)}function productDataEqual(snapBefore,snapAfter){if(!snapBefore||!snapAfter)return false;var b=JSON.parse(JSON.stringify(snapBefore));var a=JSON.parse(JSON.stringify(snapAfter));delete b.sync;delete a.sync;return JSON.stringify(b)===JSON.stringify(a)}function normalizeAuthUser(res){if(!res||!res.ok)return null;if(res.user)return res.user;if(res.data&&(res.data.userId||res.data.email)){return{id:res.data.userId,userId:res.data.userId,email:res.data.email,isAnonymous:res.data.isAnonymous,sessionExpiresAt:res.data.sessionExpiresAt}}return null}function extractRows(res){if(!res)return[];if(Array.isArray(res.data))return res.data;if(res.data&&Array.isArray(res.data.data))return res.data.data;if(res.data&&res.data.data&&Array.isArray(res.data.data.data))return res.data.data.data;return[]}var ZadSync={};ZadSync.checkAuth=function(){if(!window.ZadAPI||!window.ZadAPI.auth){return Promise.resolve({ok:false,reason:"ZadAPI_MISSING"})}return window.ZadAPI.auth.me().then(function(res){var user=normalizeAuthUser(res);if(user){return{ok:true,user:user}}return{ok:false,reason:"NO_SESSION"}}).catch(function(err){return{ok:false,reason:"AUTH_ERROR",detail:String(err)}})};ZadSync.syncNow=function(){var log_date=todayDate();var idempotency=makeIdempotencyKey(log_date);var snapBefore=null;var snapAfter=null;try{snapBefore=readLocalState()}catch(e){snapBefore=null}var hashBefore=hashObject(snapBefore);if(!window.ZadAPI||!window.ZadAPI.auth||!window.ZadAPI.worship){return Promise.resolve({ok:false,status:"SKIP",message:"ZadAPI not available",version:ZAD_VERSION})}return window.ZadAPI.auth.me().then(function(authRes){var authUser=normalizeAuthUser(authRes);if(!authUser){return{ok:false,status:"AUTH_REQUIRED",message:"No active session — login required",version:ZAD_VERSION}}if(!snapBefore){return{ok:false,status:"SKIP",message:"zad_v2 not found in localStorage",version:ZAD_VERSION}}var payload=buildWorshipPayload(snapBefore,log_date);return window.ZadAPI.worship.push(log_date,payload,idempotency).then(function(pushRes){if(!pushRes||!pushRes.ok){return{ok:false,status:"PUSH_FAILED",message:pushRes&&pushRes.error||"Push failed",user:authUser,log_date:log_date,version:ZAD_VERSION}}return window.ZadAPI.worship.list().then(function(listRes){var readback=null;var readbackSource=null;var pushedAt=(new Date).toISOString();var listRows=extractRows(listRes);if(listRows.length>0){var found=listRows.find(function(r){return r.log_date&&String(r.log_date).slice(0,10)===log_date})||null;if(found){readback=found;readbackSource="list"}}if(!readback&&pushRes&&pushRes.data){var pushed=pushRes.data.data||pushRes.data;if(pushed&&pushed.log_date&&String(pushed.log_date).slice(0,10)===log_date){readback=pushed;readbackSource="pushResponseFallback"}}snapAfter=readLocalState();hashAfter=hashObject(snapAfter);var equal=productDataEqual(snapBefore,snapAfter);writeSyncMeta({lastPushedAt:pushedAt,lastPushedDate:log_date,lastPushedStatus:"ok"});return{ok:true,status:pushRes.cached?"CACHED":"PUSHED",message:pushRes.cached?"Idempotent — same key returned cached (no DB mutation)":"Pushed and written to DB",user:authUser,log_date:log_date,idempotency_key:idempotency,pushedAt:pushedAt,pushResponse:pushRes,readback:readback,readbackSource:readbackSource,localIntegrity:{hashBefore:hashBefore,hashAfter:hashAfter,productDataEqual:equal},version:ZAD_VERSION}})})}).catch(function(err){return{ok:false,status:"ERROR",message:String(err),version:ZAD_VERSION}});var hashAfter};ZadSync.previewPayload=function(){var log_date=todayDate();var state=readLocalState();if(!state){return{ok:false,message:"zad_v2 not found"}}return{ok:true,log_date:log_date,payload:buildWorshipPayload(state,log_date),hashNow:hashObject(state)}};ZadSync.getLocalIntegrity=function(){var state=readLocalState();return{found:!!state,hash:hashObject(state),hasSyncMeta:!!(state&&state.sync)}};ZadSync.clearSyncMeta=function(){try{var raw=localStorage.getItem(ZAD_LS_KEY);if(!raw)return false;var state=JSON.parse(raw);delete state.sync;localStorage.setItem(ZAD_LS_KEY,JSON.stringify(state));return true}catch(e){return false}};window.ZadSync=ZadSync})();